        }else{
            echo "
                <div class='col-xl-12 mb-4'>
                    <div class='card'>
                        <div class='card-header py-3 d-flex flex-row align-items-center justify-content-between'>
                            <h6 class='m-0 font-weight-bold text-primary'>Kelas Praktikum Aktif</h6>
                        </div>
                        <div class='table-responsive p-3'>
                            <table class='table align-items-center table-flush table-hover' id='tablehome'>
                                <thead class='thead-light'>
                                    <tr>
                                        <th class='d-none d-md-table-cell'>ID Kelas</th>
                                        <th>Nama Kelas</th>
                                        <th>Jadwal</th>
                                        <th>Peranan</th>
                                        <th class='d-none d-md-table-cell'>Jumlah Mahasiswa</th>
                                        <th class='d-none d-md-table-cell'>Status</th>
                                    </tr>
                                </thead>
                                <tbody>
            ";
            
            while($resultgetenroled = $getenroled -> fetch_assoc()){
                $statuskelas = getkelasbyid($resultgetenroled['kelas_kode']);
                if($statuskelas != NULL){
                    $periodekelas = getperiodebyid($statuskelas['periode_kode']);
                }
                $jmlmhskelas = getjumlahkelas($resultgetenroled['kelas_kode']);

                if(($statuskelas != NULL) && ($periodekelas != NULL) && ($jmlmhskelas != NULL)){
                    if($statuskelas['status'] != "Non-Aktif"){
                        $datapraktikum = getpraktikumbyid($statuskelas['praktikum_kode']);

                        $rolekelas = namerole($resultgetenroled['role_kelas']);
                        
                        echo "
                            <tr>
                                <td class='d-none d-md-table-cell'>".$statuskelas['kelas_kode']."</td>
                                <td><a href='".LINK_kelas($statuskelas['kelas_kode'])."'>Kelas Praktikum ".$datapraktikum['fullname']." (".$datapraktikum['shortname'].") - ".$periodekelas['nama_periode']."</a></td>
                                <td>".ucwords($statuskelas['jadwal'])."</td>
                                <td>".$rolekelas."</td>
                                <td class='d-none d-md-table-cell'>".$jmlmhskelas['jumlah']."</td>
                                <td class='d-none d-md-table-cell'><span class='badge badge-success'>".$statuskelas['status']."</span></td>
                            </tr>   
                        ";
                    }
                }
            }
            echo "                       
                                </tbody>
                            </table>
                        </div>
                        <div class='card-footer'></div>
                    </div>
                </div>

            ";
